# Gateway Middleware para Transcodificação DICOM-Web em Formato Legado

Aqui está um código Node.js completo para um gateway middleware que converte requisições DICOM-Web em um formato proprietário legado usando processamento acelerado por GPU:

```javascript
// Importação das bibliotecas necessárias
const express = require('express');
const bodyParser = require('body-parser');
const dicomParser = require('dicom-parser');
const { spawn } = require('child_process');
const fs = require('fs');
const path = require('path');
const { v4: uuidv4 } = require('uuid');

// Configuração do servidor Express
const app = express();
const PORT = process.env.PORT || 3000;

// Middleware para parsing de requisições
app.use(bodyParser.raw({ type: 'application/dicom', limit: '50mb' }));
app.use(bodyParser.json());
app.use(bodyParser.urlencoded({ extended: true }));

// Configuração do processamento GPU (usando CUDA como exemplo)
const GPU_ACCELERATION = process.env.GPU_ACCELERATION || 'cuda';
const LEGACY_FORMAT = process.env.LEGACY_FORMAT || 'proprietary_legacy_format';

// Rota principal para transcodificação DICOM-Web
app.post('/dicom-web/transcode', async (req, res) => {
    try {
        // Verifica se a requisição contém dados DICOM
        if (!req.is('application/dicom') && !req.is('multipart/related')) {
            return res.status(400).json({ error: 'Requisição deve ser no formato DICOM-Web' });
        }

        // Gera um ID único para o processo
        const processId = uuidv4();
        const tempDir = path.join(__dirname, 'temp', processId);

        // Cria diretório temporário
        if (!fs.existsSync(tempDir)) {
            fs.mkdirSync(tempDir, { recursive: true });
        }

        // Salva o arquivo DICOM recebido
        const dicomFilePath = path.join(tempDir, 'input.dcm');
        fs.writeFileSync(dicomFilePath, req.body);

        // Processa o arquivo DICOM para extrair metadados
        const dicomData = parseDicomFile(dicomFilePath);

        // Converte o arquivo DICOM para um formato intermediário (PNG por exemplo)
        const intermediateFilePath = path.join(tempDir, 'intermediate.png');
        await convertDicomToPng(dicomFilePath, intermediateFilePath);

        // Processa a imagem usando GPU para transcodificação
        const legacyFilePath = path.join(tempDir, `output.${LEGACY_FORMAT}`);
        await processWithGPU(intermediateFilePath, legacyFilePath);

        // Lê o arquivo transcodificado
        const legacyData = fs.readFileSync(legacyFilePath);

        // Envia a resposta com o formato legado
        res.set('Content-Type', `application/${LEGACY_FORMAT}`);
        res.set('Content-Disposition', `attachment; filename="output.${LEGACY_FORMAT}"`);
        res.send(legacyData);

        // Limpa arquivos temporários após um tempo
        setTimeout(() => {
            fs.rmSync(tempDir, { recursive: true, force: true });
        }, 30000);

    } catch (error) {
        console.error('Erro no processamento:', error);
        res.status(500).json({ error: 'Erro no processamento da imagem' });
    }
});

