# Service Worker para PWA com Cache Dinâmico e Web Push Notifications

Aqui está um Service Worker completo para uma Progressive Web App (PWA) que inclui:
- Cache dinâmico para recursos offline
- Gerenciamento de notificações push
- Estratégias de cache avançadas
- Atualização segura do Service Worker

```javascript
// service-worker.js

// Configurações do Service Worker
const CACHE_NAME = 'pwa-cache-v1';
const DYNAMIC_CACHE_NAME = 'pwa-dynamic-cache-v1';
const ASSETS_TO_CACHE = [
  '/',
  '/index.html',
  '/styles/main.css',
  '/scripts/main.js',
  '/images/logo.png',
  '/manifest.json'
];

// Instalação do Service Worker
self.addEventListener('install', (event) => {
  console.log('[Service Worker] Installing...');

  // Cache inicial dos assets essenciais
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then((cache) => {
        console.log('[Service Worker] Caching app shell');
        return cache.addAll(ASSETS_TO_CACHE);
      })
      .then(() => self.skipWaiting()) // Ativa imediatamente
  );
});

// Ativação do Service Worker
self.addEventListener('activate', (event) => {
  console.log('[Service Worker] Activating...');

  // Limpa caches antigos
  event.waitUntil(
    caches.keys().then((cacheNames) => {
      return Promise.all(
        cacheNames.map((cacheName) => {
          if (cacheName !== CACHE_NAME && cacheName !== DYNAMIC_CACHE_NAME) {
            console.log('[Service Worker] Deleting old cache:', cacheName);
            return caches.delete(cacheName);
          }
        })
      );
    })
  );

  // Ativa imediatamente
  return self.clients.claim();
});

// Estratégia de cache: Cache First com fallback para rede
const cacheFirst = async (request) => {
  const cachedResponse = await caches.match(request);
  return cachedResponse || fetch(request);
};

// Estratégia de cache: Network First com cache fallback
const networkFirst = async (request) => {
  try {
    const networkResponse = await fetch(request);
    // Atualiza o cache com a resposta da rede
    const cache = await caches.open(DYNAMIC_CACHE_NAME);
    cache.put(request, networkResponse.clone());
    return networkResponse;
  } catch (error) {
    // Se falhar, tenta pegar do cache
    const cachedResponse = await caches.match(request);
    return cachedResponse;
  }
};

// Estratégia de cache: Stale While Revalidate
const staleWhileRevalidate = async (request) => {
  const cache = await caches.open(DYNAMIC_CACHE_NAME);
  const cachedResponse = await cache.match(request);

  // Retorna a resposta em cache imediatamente
  if (cachedResponse) {
    // Atualiza o cache em segundo plano
    fetch(request)
      .then((networkResponse) => {
        cache.put(request, networkResponse.clone());
      })
      .catch(() => console.log('Network request failed in staleWhileRevalidate'));
    return cachedResponse;
  }

  // Se não estiver em cache, faz a requisição na rede
  const networkResponse = await fetch(request);
  cache.put(request, networkResponse.clone());
  return networkResponse;
};

// Intercepta requisições de rede
