// Configurações padrão
const config = {
    outputDir: './output',
    defaultPdfOptions: {
        format: 'A4',
        margin: {
            top: '20mm',
            right: '20mm',
            bottom: '20mm',
            left: '20mm'
        },
        printBackground: true,
        preferCSSPageSize: true
    }
};

// Função para criar diretório de saída se não existir
function ensureOutputDir() {
