  const doc = new pdfkit();
  doc.pipe(fs.createWriteStream(outputPath));

  // Adiciona título
  doc.fontSize(25).text('Relatório JSON', { align: 'center' });
  doc.moveDown();

  // Adiciona tabela
  const table = {
    headers: Object.keys(jsonData[0]),
    rows: jsonData.map(item => Object.values(item))
  };

  // Configurações da tabela
  const tableOptions = {
    prepareHeader: () => doc.font('Helvetica-Bold'),
    prepareRow: (row, indexColumn, indexRow, rectRow) => doc.font('Helvetica'),
  };

  // Desenha a tabela
  doc.table(table, tableOptions);

  // Finaliza o PDF
  doc.end();
  console.log(`PDF gerado em: ${outputPath}`);
}

