    let html = '<html><head><style>table { width: 100%; border-collapse: collapse; } th, td { border: 1px solid #ddd; padding: 8px; text-align: left; } th { background-color: #f2f2f2; }</style></head><body>';

    if (Array.isArray(jsonData)) {
        html += '<table><thead><tr>';
        Object.keys(jsonData[0]).forEach(key => {
            html += `<th>${key}</th>`;
        });
        html += '</tr></thead><tbody>';

        jsonData.forEach(item => {
            html += '<tr>';
            Object.values(item).forEach(value => {
                html += `<td>${value}</td>`;
            });
            html += '</tr>';
        });

        html += '</tbody></table>';
    } else {
        html += '<pre>' + JSON.stringify(jsonData, null, 2) + '</pre>';
    }

    html += '</body></html>';
    return html;
}

